import glob
classify_files = glob.glob('/root/autodl-tmp/outputs/*/classify*.json')
for f in sorted(classify_files):
    try:
        with open(f) as fh:
            data = json.load(fh)

        if isinstance(data, dict):
            # Check for h7_count or ts_count
            if 'h7_count' in data or 'ts_count' in data:
                h7 = data.get('h7_count', data.get('ts_count', 0))
                if h7 > 0:
                    ts_sources.append((f, h7))
            # Check for per-sample results
            elif 'samples' in data or 'results' in data:
                samples = data.get('samples', data.get('results', []))
                if isinstance(samples, list):
                    ts_count = sum(1 for s in samples if isinstance(s, dict) and s.get('label') == 'TS' or s.get('classification') == 'TS' or s.get('classify_result') == 'TS')
