                    total = ts_count + h7_count
                    if total > 0:
                        ts_sources.append((f, total))
        elif isinstance(data, list):
            ts_count = sum(1 for s in data if isinstance(s, dict) and (s.get('label') == 'TS' or s.get('classification') == 'TS' or s.get('classify_result') == 'TS'))
